import { cpuSeconds, memorySnapshot, stackBytes } from "./process.js";
import { cpuProfile, emptyProfile, memoryProfile, stackProfile, } from "./profile/pprof.js";
export const ProfileNameKey = Symbol("gotots.pprof.profile-name");
let activeCpuProfile;
export function startCpuSample() {
    return {
        startedAt: Date.now(),
        cpuAtStart: cpuSeconds(),
    };
}
export function finishCpuSample(sample) {
    const stoppedAt = Date.now();
    return cpuProfile(sample.startedAt, stoppedAt, Math.max(0, cpuSeconds() - sample.cpuAtStart));
}
export function beginCpuProfile(write) {
    if (activeCpuProfile !== undefined) {
        return false;
    }
    activeCpuProfile = {
        sample: startCpuSample(),
        write,
    };
    return true;
}
export function finishCpuProfile() {
    const session = activeCpuProfile;
    activeCpuProfile = undefined;
    if (session !== undefined) {
        session.write(finishCpuSample(session.sample));
    }
}
export function profileSnapshot(name) {
    switch (name) {
        case "allocs":
        case "heap":
            return memoryProfile(name, memorySnapshot());
        case "goroutine":
            return stackProfile(stackBytes());
        case "block":
        case "mutex":
        case "threadcreate":
            return emptyProfile(name);
        default:
            return new Uint8Array();
    }
}
export function knownProfile(name) {
    switch (name) {
        case "allocs":
        case "block":
        case "goroutine":
        case "heap":
        case "mutex":
        case "threadcreate":
            return true;
        default:
            return false;
    }
}
